import { GoogleSignin } from '@react-native-google-signin/google-signin';

export const configureGoogleSignIn = () => {
  GoogleSignin.configure({
    webClientId: '142052743063-he47ba59ocqbqphde7550n3bp14qafom.apps.googleusercontent.com', // Replace with your Web Client ID
    offlineAccess: true, // Required for Android
  });
};
